-- 4. Verifikasi
-- ----------------------------------------------------------------------------
SELECT 'Rumah Tangga:' AS label, COUNT(*)::text AS jumlah
  FROM households WHERE tenant_id = '00000000-0000-0000-0000-000000000011'
UNION ALL
SELECT 'Warga:', COUNT(*)::text
  FROM residents WHERE tenant_id = '00000000-0000-0000-0000-000000000011'
UNION ALL
SELECT 'KK berkoordinat:', COUNT(*)::text
  FROM households WHERE tenant_id = '00000000-0000-0000-0000-000000000011' AND latitude IS NOT NULL;
